import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as r,c as s,o as a,ag as e,G as i}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const w=JSON.parse('{"title":"NetEase UU Remote tutorial","description":"NetEase UU Remote is remote control software: when you are not at the computer, you can still see its screen, operate it and retrieve its files from a phone, a tablet or another computer. This page gets both ends installed, connects you to a first computer with a device ID plus a verification code, and then teaches unattended access, remote wake-up, file transfer and privacy mode.","frontmatter":{"title":"NetEase UU Remote tutorial","description":"NetEase UU Remote is remote control software: when you are not at the computer, you can still see its screen, operate it and retrieve its files from a phone, a tablet or another computer. This page gets both ends installed, connects you to a first computer with a device ID plus a verification code, and then teaches unattended access, remote wake-up, file transfer and privacy mode.","domain":"product","tags":["remote-control","remote-desktop","netease"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"products/uu-remote/uu-remote.md","filePath":"products/uu-remote/uu-remote.md","lastUpdated":1795792629000}'),d={name:"products/uu-remote/uu-remote.md"};function l(h,t,c,p,u,g){const o=r("DocDiagram");return a(),s("div",null,[t[0]||(t[0]=e("",48)),i(o,{src:"/diagrams/uu-remote-connect.en.svg",alt:"This sequence diagram answers one question, in numbered order: after you enter a device ID and verification code on the controller, how do picture and input travel between the two devices? It has three objects: the controller, which is the device in your hands; the controlled computer, which is the computer being operated; and the NetEase service, drawn as a single box. Step 1: the controller sends the device ID and verification code of the controlled computer to the NetEase service. Step 2: the NetEase service verifies and connects. Its internal steps are not published, so the diagram shows only one box: it does not show how verification works or whether data travels directly or through a relay. Once the connection is established, the two ends send and receive data. Step 3: the controlled computer captures the screen and audio, encodes them into a stream, and sends it continuously to the controller. This is the heavy, downstream direction. Step 4: the controller sends keyboard, mouse, and touch events to the controlled computer. This is the light, upstream direction. Step 5: the controlled computer runs the input, the screen changes, and the flow returns to step 3. Steps 3 to 5 repeat for every input. The two data streams of steps 3 and 4 sit inside a dashed frame, which marks that NetEase calls the traffic between the two ends end-to-end encrypted. The cipher, codecs, transport protocol, ports, and latency are not published, and the diagram does not show them. On the controller side, the work is to decode and show the picture, play audio, and capture your keyboard, mouse, and touch input. On the controlled side, the work is to capture the screen and audio and to run the input.",width:1020,lang:"en"}),t[1]||(t[1]=e("",118))])}const b=n(d,[["render",l]]);export{w as __pageData,b as default};
